import java.util.*;
public class  Main{
    static final long MOD = 998244353L;
public static void main(String[] args){
    Scanner sc= new Scanner (System.in);
    int t= sc.nextInt();
    while(t-- > 0){
        int n= sc.nextInt();
        long[] a =  new long[n];
        for(int i=0;i<n;i++){
            a[i]=sc.nextLong();
        }
        long[] harmonic = new long[n+1];
        for(int i=1;i<n;i++){
            long inverse = power(i, MOD - 2);
            harmonic[i]=(harmonic[i-1] + inverse) % MOD;
        }
        long answer = 0;
        for(int i=0;i<n;i++){
            long coff= (harmonic[i]+harmonic[n-i-1])%MOD;
            answer = (answer+a[i]*coff)%MOD;
        }
        System.out.println(answer);
    }
    sc.close();
}
static long power(long x,long y){
    long result =1;
    while(y>0){
        if((y &1 )== 1){
            result = result*x % MOD;
        }
        x=x*x %MOD;
        y/=2;
    }
    return result;
}
}
